const MOD = 998244353;

function modInv(a, mod = MOD) {
    let m = mod - 2;
    let res = 1n;
    let base = BigInt(a % mod);
    while (m > 0) {
        if (m & 1n) res = (res * base) % BigInt(mod);
        base = (base * base) % BigInt(mod);
        m >>= 1n;
    }
    return Number(res);
}

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(' ').map(Number);
    const p = input[0];
    const s = input[1];
    const r = input[2];

    const maxS = s;
    const maxP = p;

    // Precompute combinations C(n, k) mod MOD
    const C = Array.from({ length: maxS + 1 }, () => new Array(maxP + 1).fill(0));
    for (let n = 0; n <= maxS; n++) {
        C[n][0] = 1;
        for (let k = 1; k <= Math.min(n, maxP); k++) {
            C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % MOD;
        }
    }

    // Precompute factorials and inverse factorials
    const fact = new Array(maxS + 1).fill(1);
    const invFact = new Array(maxS + 1).fill(1);
    for (let i = 1; i <= maxS; i++) {
        fact[i] = Number((BigInt(fact[i - 1]) * BigInt(i)) % BigInt(MOD));
    }
    invFact[maxS] = modInv(fact[maxS]);
    for (let i = maxS - 1; i >= 0; i--) {
        invFact[i] = Number((BigInt(invFact[i + 1]) * BigInt(i + 1)) % BigInt(MOD));
    }

    // dp[i][j][k] = number of ways for first i players, sum j, max score k
    const dp = Array.from({ length: p + 1 }, () => 
        Array.from({ length: s + 1 }, () => new Array(s + 1).fill(0))
    );

    dp[0][0][0] = 1;
    for (let i = 1; i <= p; i++) {
        for (let j = 0; j <= s; j++) {
            for (let k = 0; k <= j; k++) {
                if (dp[i - 1][j][k] === 0) continue;
                for (let x = 0; x <= s - j; x++) {
                    const newJ = j + x;
                    const newK = Math.max(k, x);
                    dp[i][newJ][newK] = (dp[i][newJ][newK] + dp[i - 1][j][k]) % MOD;
                }
            }
        }
    }

    // Calculate total valid states where a1 >= r
    let total = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const remaining = s - a1;
        if (remaining < 0) continue;
        // Number of ways to distribute remaining among p-1 players
        if (p === 1) {
            if (remaining === 0) total = (total + 1) % MOD;
            continue;
        }
        // Using stars and bars: C(remaining + p - 2, p - 2)
        const n = remaining + p - 2;
        const k = p - 2;
        if (n >= 0 && k >= 0 && n >= k) {
            total = (total + C[n][k]) % MOD;
        }
    }

    // Calculate winning states
    let win = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const remaining = s - a1;
        if (remaining < 0) continue;
        if (p === 1) {
            if (remaining === 0) win = (win + 1) % MOD;
            continue;
        }
        // Calculate ways where all other players have score < a1
        // This is equivalent to distributing 'remaining' into (p-1) players, each < a1
        // Using inclusion-exclusion
        let ways = 0;
        for (let mask = 0; mask < (1 << (p - 1)); mask++) {
            let cnt = 0;
            let sum = 0;
            for (let bit = 0; bit < p - 1; bit++) {
                if (mask & (1 << bit)) {
                    cnt++;
                    sum += a1;
                }
            }
            if (sum > remaining) continue;
            const rem = remaining - sum;
            const n = rem + p - 2;
            const k = p - 2;
            if (n >= 0 && k >= 0 && n >= k) {
                const comb = C[n][k];
                if (cnt % 2 === 0) {
                    ways = (ways + comb) % MOD;
                } else {
                    ways = (ways - comb + MOD) % MOD;
                }
            }
        }
        win = (win + ways) % MOD;
    }

    // Calculate tie states
    let tie = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const remaining = s - a1;
        if (remaining < 0) continue;
        if (p === 1) continue;
        // Calculate ways where at least one other player has score == a1
