            if (n >= 0 && k >= 0 && n >= k) {
                const comb = C[n][k];
                if (cnt % 2 === 0) {
                    lessWays = (lessWays + comb) % MOD;
                } else {
                    lessWays = (lessWays - comb + MOD) % MOD;
                }
            }
        }
        const tieWays = (totalWays - lessWays + MOD) % MOD;
        tie = (tie + tieWays) % MOD;
    }

    // Probability = win + tie * (1 / number of top scorers)
    // But we need to calculate the expected value of 1/(number of top scorers) for tie states
    // This is complex, so let's use the dp approach instead

    // Recalculate using dp
    win = 0;
    tie = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const remaining = s - a1;
        if (remaining < 0) continue;
        if (p === 1) {
            if (remaining === 0) win = (win + 1) % MOD;
            continue;
        }
        // Use dp to find number of ways where max of other players < a1
        // and max of other players == a1
        let less = 0;
        let equal = 0;
        for (let mask = 0; mask < (1 << (p - 1)); mask++) {
            let cnt = 0;
            let sum = 0;
            for (let bit = 0; bit < p - 1; bit++) {
                if (mask & (1 << bit)) {
                    cnt++;
                    sum += a1;
                }
            }
            if (sum > remaining) continue;
            const rem = remaining - sum;
            const n = rem + p - 2;
            const k = p - 2;
            if (n >= 0 && k >= 0 && n >= k) {
                const comb = C[n][k];
                if (cnt % 2 === 0) {
                    less = (less + comb) % MOD;
                } else {
                    less = (less - comb + MOD) % MOD;
                }
            }
        }
        // For equal, we need at least one player with exactly a1
        // This is total - less
        let totalWays = 0;
        for (let mask = 0; mask < (1 << (p - 1)); mask++) {
            let cnt = 0;
            let sum = 0;
            for (let bit = 0; bit < p - 1; bit++) {
                if (mask & (1 << bit)) {
                    cnt++;
                    sum += a1;
                }
            }
            if (sum > remaining) continue;
            const rem = remaining - sum;
            const n = rem + p - 2;
            const k = p - 2;
            if (n >= 0 && k >= 0 && n >= k) {
                const comb = C[n][k];
                if (cnt % 2 === 0) {
                    totalWays = (totalWays + comb) % MOD;
                } else {
                    totalWays = (totalWays - comb + MOD) % MOD;
                }
            }
        }
        equal = (totalWays - less + MOD) % MOD;
        win = (win + less) % MOD;
        tie = (tie + equal) % MOD;
    }

    // For tie states, we need to calculate the expected value of 1/(number of top scorers)
    // This requires a more complex calculation
    // Let's use the dp approach to calculate this

    // Recalculate tie contribution
    let tieContribution = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const remaining = s - a1;
        if (remaining < 0) continue;
        if (p === 1) continue;
        // For each way where at least one other player has a1,
        // calculate the expected value of 1/(number of players with a1)
        // This is complex, so let's use a different approach
        // We need to count, for each possible number of players with a1,
        // the number of ways and multiply by 1/(that number + 1)
        for (let cnt = 1; cnt <= p - 1; cnt++) {
            // Number of ways to choose 'cnt' players out of p-1 to have score a1
            const choose = C[p - 1][cnt];
