const MOD = 998244353;

function modInverse(a, mod = MOD) {
    let m = mod, y = 0, x = 1;
    while (a > 1) {
        const q = Math.floor(a / m);
        let t = m;
        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    if (x < 0) x += mod;
    return x;
}

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(' ').map(Number);
    let p = input[0], s = input[1], r = input[2];

    // Precompute factorials and inverse factorials up to s
    let maxN = s;
    let fact = new Array(maxN + 1).fill(1);
    let invFact = new Array(maxN + 1).fill(1);
    for (let i = 1; i <= maxN; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    invFact[maxN] = modInverse(fact[maxN]);
    for (let i = maxN - 1; i >= 0; i--) {
        invFact[i] = invFact[i + 1] * (i + 1) % MOD;
    }

    // Compute comb(n, k)
    function comb(n, k) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    // Compute C(n, k) = comb(n + k - 1, k)
    function C(n, k) {
        if (n <= 0) return k === 0 ? 1 : 0;
        return comb(n + k - 1, k);
    }

    // Compute the number of non-negative solutions to x1 + ... + xn = k, with each xi <= c
    function countBounded(n, k, c) {
        if (k < 0) return 0;
        let res = 0;
        for (let i = 0; i <= n; i++) {
            let term = comb(n, i) * C(n, k - i * (c + 1)) % MOD;
            if (i % 2 === 0) {
                res = (res + term) % MOD;
            } else {
                res = (res - term + MOD) % MOD;
            }
        }
        return res;
    }

    // Total number of valid states
    let totalStates = 0;
    for (let a1 = r; a1 <= s; a1++) {
        let rem = s - a1;
        if (rem < 0) break;
        totalStates = (totalStates + C(p - 1, rem)) % MOD;
    }

    // Number of winning states
    let winningStates = 0;
    for (let a1 = r; a1 <= s; a1++) {
        let rem = s - a1;
        if (rem < 0) break;
        // Case 1: all others < a1
        let case1 = countBounded(p - 1, rem, a1 - 1);
        // Case 2: at least one other == a1
        let case2 = (C(p - 1, rem) - countBounded(p - 1, rem, a1 - 1) + MOD) % MOD;
        // Contribution from case2: 1/(t+1) where t is the number of others equal to a1
        // Sum over all possible t (from 1 to p-1)
        let case2Contrib = 0;
        for (let t = 1; t <= p - 1; t++) {
            // Choose t players to have a1, remaining (p-1 - t) players have sum rem - t*a1, each < a1
            let waysChoose = comb(p - 1, t);
            let remSum = rem - t * a1;
            if (remSum < 0) continue;
            let waysRem = countBounded(p - 1 - t, remSum, a1 - 1);
            let prob = modInverse(t + 1);
            case2Contrib = (case2Contrib + waysChoose * waysRem % MOD * prob) % MOD;
        }
        winningStates = (winningStates + case1 + case2Contrib) % MOD;
    }

    // Probability is winningStates / totalStates
    let invTotal = modInverse(totalStates);
    let result = winningStates * invTotal % MOD;
    console.log(result);
}

main();
