const MOD = 998244353;

function modInv(a, mod) {
    let g = mod, h = a % mod;
    let x = 0, y = 1;
    while (g !== 0) {
        const q = Math.floor(h / g);
        [x, y] = [y, x - q * y];
        [g, h] = [h % g, g];
    }
    return (x % mod + mod) % mod;
}

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
    const p = input[0];
    const s = input[1];
    const r = input[2];

    // Precompute factorials and inverse factorials up to s
    const maxFact = s;
    const fact = new Array(maxFact + 1).fill(1n);
    for (let i = 1n; i <= BigInt(maxFact); i++) {
        fact[Number(i)] = (fact[Number(i) - 1] * i) % BigInt(MOD);
    }
    const invFact = new Array(maxFact + 1).fill(1n);
    invFact[maxFact] = modInv(Number(fact[maxFact]), MOD);
    for (let i = maxFact - 1; i >= 0; i--) {
        invFact[i] = (invFact[i + 1] * BigInt(i + 1)) % BigInt(MOD);
    }

    function comb(n, k) {
        if (n < 0 || k < 0 || n < k) return 0n;
        return (fact[n] * invFact[k] % BigInt(MOD)) * invFact[n - k] % BigInt(MOD);
    }

    // Compute total number of valid states
    let total = 0n;
    for (let a1 = r; a1 <= s; a1++) {
        const rem = s - a1;
        if (rem < 0) break;
        total = (total + comb(rem + p - 2, p - 2)) % BigInt(MOD);
    }

    // Compute winning states
    let win = 0n;
    for (let a1 = r; a1 <= s; a1++) {
        const rem = s - a1;
        if (rem < 0) break;
        // Case 1: all others < a1
        let case1 = 0n;
        for (let k = 0; k <= p - 1; k++) {
            const term = comb(p - 1, k) * comb(rem - k * a1 + p - 2, p - 2);
            if (k % 2 === 0) {
                case1 = (case1 + term) % BigInt(MOD);
            } else {
                case1 = (case1 - term + BigInt(MOD)) % BigInt(MOD);
            }
        }
        win = (win + case1) % BigInt(MOD);

        // Case 2: exactly m others equal to a1
        for (let m = 1; m <= p - 1; m++) {
            if (m * a1 > rem) break;
            const rem2 = rem - m * a1;
            if (rem2 < 0) continue;
            // Number of ways to choose m players and assign a1 to them
            const waysChoose = comb(p - 1, m);
            // Number of ways to distribute rem2 among (p-1 - m) players with each < a1
            let waysDist = 0n;
            for (let k = 0; k <= p - 1 - m; k++) {
                const term = comb(p - 1 - m, k) * comb(rem2 - k * a1 + (p - 1 - m) - 1, (p - 1 - m) - 1);
                if (k % 2 === 0) {
                    waysDist = (waysDist + term) % BigInt(MOD);
                } else {
                    waysDist = (waysDist - term + BigInt(MOD)) % BigInt(MOD);
                }
            }
            const contribution = (waysChoose * waysDist) % BigInt(MOD);
            contribution = (contribution * modInv(m + 1, MOD)) % BigInt(MOD);
            win = (win + contribution) % BigInt(MOD);
        }
    }

    const invTotal = modInv(Number(total), MOD);
    const ans = (win * BigInt(invTotal)) % BigInt(MOD);
    console.log(Number(ans));
}

