    for (let n = 0; n <= maxN; n++) {
        C[n][0] = 1;
        if (n > 0) {
            for (let k = 1; k <= n; k++) {
                C[n][k] = (C[n-1][k-1] + C[n-1][k]) % MOD;
            }
        }
    }

    // Precompute inverse of p mod MOD
    const invP = modInv(p, MOD);

    // dp[i][j] = number of ways to distribute j points among i players (each >=0)
    const dp = Array.from({ length: p + 1 }, () => new Array(s + 1).fill(0));
    for (let i = 0; i <= p; i++) {
        dp[i][0] = 1;
    }
    for (let i = 1; i <= p; i++) {
        for (let j = 0; j <= s; j++) {
            dp[i][j] = dp[i-1][j];
            if (j > 0) {
                dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD;
            }
        }
    }

    // Calculate total valid states: a1 >= r, sum = s, all >=0
    let total = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const rem = s - a1;
        if (rem < 0) continue;
        total = (total + dp[p-1][rem]) % MOD;
    }

    // Calculate winning states
    let win = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const rem = s - a1;
        if (rem < 0) continue;
        // Case 1: all others < a1
        let case1 = 0;
        for (let k = 0; k <= p-1; k++) {
            const maxOthers = a1 - 1;
            if (maxOthers < 0) break;
            // Inclusion-exclusion for sum <= rem with each <= maxOthers
            let val = 0;
            for (let i = 0; i <= k; i++) {
                const term = C[k][i] * dp[p-1-k][rem - i*(maxOthers+1)] % MOD;
                if (i % 2 === 0) {
                    val = (val + term) % MOD;
                } else {
                    val = (val - term + MOD) % MOD;
                }
            }
            case1 = (case1 + C[p-1][k] * val) % MOD;
        }
        win = (win + case1) % MOD;

        // Case 2: exactly m others have a1, rest < a1
        for (let m = 1; m <= p-1; m++) {
            const needed = m * a1;
            if (needed > rem) break;
            const rem2 = rem - needed;
            // Choose m players to have a1, rest (p-1-m) have < a1 and sum to rem2
            let ways = C[p-1][m];
            // Distribute rem2 among (p-1-m) players each < a1
            let val = 0;
            for (let i = 0; i <= p-1-m; i++) {
                const term = C[p-1-m][i] * dp[p-1-m-i][rem2 - i*a1] % MOD;
                if (i % 2 === 0) {
                    val = (val + term) % MOD;
                } else {
                    val = (val - term + MOD) % MOD;
                }
            }
            ways = ways * val % MOD;
            // Probability contribution: 1/(m+1)
            const prob = ways * modInv(m + 1, MOD) % MOD;
            win = (win + prob) % MOD;
        }
    }

    // Result = win / total mod MOD
    const result = win * modInv(total, MOD) % MOD;
    console.log(result);
}

