```javascript
const MOD = 998244353;

function modinv(x) {
    return pow(x, MOD - 2);
}

function pow(x, n) {
    let res = 1;
    while (n > 0) {
        if (n % 2 === 1) res = res * x % MOD;
        x = x * x % MOD;
        n = Math.floor(n / 2);
    }
    return res;
}

function main() {
    const [p, s, r] = readline().split(' ').map(Number);
    const maxN = s + 1;
    const C = Array.from({ length: maxN }, () => new Array(maxN).fill(0));
    for (let n = 0; n < maxN; n++) {
        C[n][0] = 1;
        for (let k = 1; k <= n; k++) {
            C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % MOD;
        }
    }

    const dp = Array.from({ length: p }, () => new Array(s + 1).fill(0));
    for (let i = 0; i < p; i++) {
        for (let j = 0; j <= s; j++) {
            if (i === 0) {
                if (j >= r) dp[i][j] = 1;
            } else {
                for (let k = 0; k <= j; k++) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD;
                }
            }
        }
    }

    let total = 0;
    for (let a1 = r; a1 <= s; a1++) {
        const rem = s - a1;
        if (rem < 0) continue;
        let ways = 0;
        for (let m = 0; m <= p - 1; m++) {
            const term = C[p - 1][m] * pow(a1, m) % MOD;
            const exp = rem - m * a1;
            if (exp < 0) break;
            const comb = C[exp + p - 1][p - 1];
            ways = (ways + term * comb) % MOD;
        }
        total = (total + ways) % MOD;
    }

    const Q = dp[p - 1][s];
    const ans = total * modinv(Q) % MOD;
    console.log(ans);
}

main();
