const MOD = 998244353;

function modInverse(a, mod) {
    let m = mod - 2, res = 1, base = a % mod;
    while (m > 0) {
        if (m & 1) res = res * base % mod;
        base = base * base % mod;
        m >>= 1;
    }
    return res;
}

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(' ').map(Number);
    const p = input[0], s = input[1], r = input[2];

    // dp[i][j][k] = number of ways to distribute j points among first i players with max score k
    let dp = Array.from({length: p+1}, () => Array.from({length: s+1}, () => new Array(s+1).fill(0)));
    dp[0][0][0] = 1;

    for (let i = 1; i <= p; i++) {
        for (let j = 0; j <= s; j++) {
            for (let k = 0; k <= j; k++) {
                if (dp[i-1][j][k] === 0) continue;
                for (let x = 0; x <= s - j; x++) {
                    let nj = j + x;
                    let nk = Math.max(k, x);
                    dp[i][nj][nk] = (dp[i][nj][nk] + dp[i-1][j][k]) % MOD;
                }
            }
        }
    }

    // Calculate total valid states where a1 >= r
    let total = 0;
    for (let a1 = r; a1 <= s; a1++) {
        let rem = s - a1;
        if (rem < 0) continue;
        for (let k = 0; k <= rem; k++) {
            total = (total + dp[p-1][rem][k]) % MOD;
        }
    }

    // Calculate winning states for Hasan
    let win = 0;
    for (let a1 = r; a1 <= s; a1++) {
        let rem = s - a1;
        if (rem < 0) continue;
        // Case 1: a1 > max of others
        for (let k = 0; k < a1; k++) {
            win = (win + dp[p-1][rem][k]) % MOD;
        }
        // Case 2: a1 == max of others (tie)
        let tieCount = dp[p-1][rem][a1];
        win = (win + tieCount * modInverse(2, MOD) % MOD) % MOD;
    }

    let ans = win * modInverse(total, MOD) % MOD;
    console.log(ans);
}

