function modInverse(a, mod) {
    let m = mod;
    let y = 0, x = 1;
    if (mod === 1) return 0;
    while (a > 1) {
        let q = Math.floor(a / m);
        let t = m;
        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    if (x < 0) x += mod;
    return x;
}

